def total(self) -> int:
    return sum(b.quantity for b in self.batches)

def usable(self, on: date) -> int:
    """Units neither expired on `on` (a batch is still usable on its expiry date) nor recalled."""
    return sum(b.quantity for b in self.batches
               if not b.recalled and (b.expiry is None or b.expiry >= on))

def to_order(self, on: date) -> int:
    """Units to order: up to twice the reorder level with what's on order, in whole packs."""
    need = max(0, 2 * self.reorder_level - self.usable(on) - self.on_order)
    return -(-need // self.pack_size) * self.pack_size

def to_reorder(items, on: date, location: str | None = None) -> list[StockItem]:
    """Items to reorder, the smallest share of their reorder level left first."""
    location = location.lower() if location is not None else None
    if location is not None and location not in LOCATIONS:
        raise ValidationError(f"location: one of {', '.join(LOCATIONS)}")
    low = [item for item in items if not item.discontinued and (location is None or item.location == location)
           and item.usable(on) <= item.reorder_level and item.usable(on) + item.on_order <= item.reorder_level]
    return sorted(low, key=lambda item: (Fraction(item.usable(on), item.reorder_level), item.code))


